    seen=set()
    for r in range(h):
      for c in range(w):
        if grid[r][c]!=3 or (r,c) in seen: continue
        comp=[]; stack=[(r,c)]; seen.add((r,c))
        while stack:
          x,y=stack.pop(); comp.append((x,y))
          for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
            if 0<=nx<h and 0<=ny<w and grid[nx][ny]==3 and (nx,ny) not in seen:
              seen.add((nx,ny)); stack.append((nx,ny))
        members=set(comp)
        for x,y in comp:
          if grid[x][y]!=2: continue
          for nx in range(max(0,x-1),min(h,x+2)):
            for ny in range(max(0,y-1),min(w,y+2)):
              if (nx,ny) in members: out[nx][ny]=1
    # Preserve all 2s; 2s are never part of component, so add their local patches via adjacency.
    # identify 2 markers adjacent to a component and color that component's cells within 3x3
    for x in range(h):
      for y in range(w):
        if grid[x][y]!=2: continue
        for nx in range(max(0,x-1),min(h,x+2)):
          for ny in range(max(0,y-1),min(w,y+2)):
            if grid[nx][ny]==3: out[nx][ny]=1
    return out

